export function TechStack() {
  return (
    <section
      id="tech"
      className="relative py-24 sm:py-32 bg-muted/30 overflow-hidden"
      aria-labelledby="tech-heading"
    >
      <div className="mx-auto max-w-7xl px-6 sm:px-8 lg:px-12">
        <motion.div
          variants={containerVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          className="text-center"
        >
          {/* Header */}
          <motion.div variants={itemVariants}>
            <p className="text-sm font-medium uppercase tracking-widest text-muted-foreground">
              Tech Stack
            </p>
            <h2
              id="tech-heading"
              className="mt-4 text-3xl sm:text-4xl font-bold tracking-tight text-foreground"
            >
              Tools I work with
            </h2>
            <p className="mt-4 text-lg text-muted-foreground max-w-2xl mx-auto">
              A curated selection of technologies and tools that power my
              development and design workflow.
            </p>
          </motion.div>
        </motion.div>
      </div>

      {/* Marquee Container */}
      <div className="mt-16 space-y-8">
        {/* First Row - Left to Right */}
        <MarqueeRow items={techStack.slice(0, 7)} direction="left" speed={25} />

        {/* Second Row - Right to Left */}
        <MarqueeRow
          items={techStack.slice(7, 14)}
          direction="right"
          speed={30}
        />
      </div>

      {/* Gradient Overlays */}
      <div className="absolute inset-y-0 left-0 w-32 bg-gradient-to-r from-muted/30 to-transparent pointer-events-none z-10" />
      <div className="absolute inset-y-0 right-0 w-32 bg-gradient-to-l from-muted/30 to-transparent pointer-events-none z-10" />
    </section>
  );
}

interface MarqueeRowProps {
  items: TechItem[];
  direction: "left" | "right";
  speed?: number;
}

function MarqueeRow({ items, direction, speed = 25 }: MarqueeRowProps) {
  // Double the items for seamless loop
  const duplicatedItems = [...items, ...items];

  return (
    <div className="relative flex overflow-hidden">
      <motion.div
        className="flex gap-8"
        animate={{
          x: direction === "left" ? [0, -50 * items.length * 2.5] : [-50 * items.length * 2.5, 0],
        }}
        transition={{
          x: {
            duration: speed,
            repeat: Infinity,
            ease: "linear",
          },
        }}
      >
        {duplicatedItems.map((tech, index) => (
          <TechCard key={`${tech.name}-${index}`} tech={tech} />
        ))}
      </motion.div>
    </div>
  );
}

interface TechCardProps {
  tech: TechItem;
}

function TechCard({ tech }: TechCardProps) {
  return (
    <div className="group flex-shrink-0">
      <div className="flex items-center gap-4 px-6 py-4 rounded-2xl border border-border bg-background hover:bg-muted/50 transition-all duration-300 hover:scale-105 hover:shadow-lg hover:shadow-muted/20 cursor-default">
        <div className="text-foreground/70 group-hover:text-foreground transition-colors">
          {tech.icon}
        </div>
        <span className="text-sm font-medium text-foreground whitespace-nowrap">
          {tech.name}
        </span>
      </div>
    </div>
  );
}
